import * as MuxRetry from "@distilled.cloud/mux/Retry";
import * as Video from "@distilled.cloud/mux/video";
import * as Provider from "alchemy/Provider";
import { Resource } from "alchemy/Resource";
import * as Effect from "effect/Effect";
import * as Stream from "effect/Stream";
import type { Providers } from "../Providers.ts";

export interface TranscriptionVocabularyProps {
  /**
   * Words, phrases or proper names (product names, speaker names, jargon)
   * whose recognition is boosted in live auto-generated captions.
   */
  phrases: string[];
  /**
   * Name shown in the Mux dashboard. Removing it clears the name on Mux.
   */
  name?: string;
  /**
   * Arbitrary metadata Mux stores with the vocabulary. Max 255 characters.
   */
  passthrough?: string;
}

export interface TranscriptionVocabularyAttributes {
  /** Mux transcription vocabulary ID. Reference it from a live stream's `generated_subtitles[].transcription_vocabulary_ids`. */
  id: string;
  /** Name shown in the Mux dashboard. */
  name: string | undefined;
  /** Phrases Mux boosts during live speech recognition. */
  phrases: string[];
  /** Metadata stored with the vocabulary. */
  passthrough: string | undefined;
  /** Unix timestamp (seconds, as a string) of creation. */
  created_at: string;
}

export type TranscriptionVocabulary = Resource<
  "Mux.Video.TranscriptionVocabulary",
  TranscriptionVocabularyProps,
  TranscriptionVocabularyAttributes,
  never,
  Providers
>;

/**
 * A Mux Transcription Vocabulary: words and phrases (product names, speaker
 * names, jargon) that improve live auto-generated captions. Reference its
 * `id` from a live stream's `generated_subtitles[].transcription_vocabulary_ids`.
 *
 * Every prop updates the vocabulary in place, so its `id` never changes.
 * @see https://www.mux.com/docs/guides/add-autogenerated-captions-and-use-transcripts
 *
 * ### Creating a Transcription Vocabulary
 * **Example:** Boost product names in live captions
 * ```typescript
 * const vocab = yield* Mux.Video.TranscriptionVocabulary("ProductTerms", {
 *   name: "Product terms",
 *   phrases: ["Mux", "Alchemy", "HLS"],
 * });
 * ```
 *
 * ### Using it on a live stream
 * **Example:** Attach the vocabulary to generated captions
 * ```typescript
 * const vocab = yield* Mux.Video.TranscriptionVocabulary("ProductTerms", {
 *   phrases: ["Mux", "Alchemy"],
 * });
 * const stream = yield* Mux.Video.LiveStream("Keynote", {
 *   playback_policies: ["public"],
 *   generated_subtitles: [
 *     { language_code: "en", transcription_vocabulary_ids: [vocab.id] },
 *   ],
 * });
 * ```
 *
 * @resource
 */
export const TranscriptionVocabulary = Resource<TranscriptionVocabulary>(
  "Mux.Video.TranscriptionVocabulary",
);

const toAttrs = (vocab: Video.TranscriptionVocabulary): TranscriptionVocabularyAttributes => ({
  id: vocab.id,
  name: vocab.name || undefined,
  phrases: vocab.phrases ?? [],
  passthrough: vocab.passthrough || undefined,
  created_at: vocab.created_at,
});

const sameStrings = (a: readonly string[], b: readonly string[]) =>
  a.length === b.length && a.every((value, i) => value === b[i]);

export const TranscriptionVocabularyProvider = () =>
  Provider.effect(
    TranscriptionVocabulary,
    Effect.gen(function* () {
      const create = yield* Video.createTranscriptionVocabulary;
      const update = yield* Video.updateTranscriptionVocabulary;
      const get = yield* Video.getTranscriptionVocabulary;
      const del = yield* Video.deleteTranscriptionVocabulary;
      const list = yield* Video.listTranscriptionVocabularies;

      const observe = (id: string) =>
        get({ TRANSCRIPTION_VOCABULARY_ID: id }).pipe(
          Effect.map((res) => toAttrs(res.data)),
          Effect.catchTag("NotFound", () => Effect.undefined),
        );

      return {
        stables: ["id", "created_at"],
        list: () =>
          list.items({ limit: 100 }).pipe(
            Stream.runCollect,
            Effect.map((vocabs) => vocabs.map(toAttrs)),
          ),
        reconcile: Effect.fn(function* ({ news, output }) {
          const observed = output?.id ? yield* observe(output.id) : undefined;

          if (observed === undefined) {
            // A create that failed with a 5xx may still have happened, so it
            // is retried only on throttling.
            const { data } = yield* create({
              name: news.name,
              phrases: news.phrases,
              passthrough: news.passthrough,
            }).pipe(MuxRetry.throttling);
            return toAttrs(data);
          }

          if (
            observed.name === news.name &&
            observed.passthrough === news.passthrough &&
            sameStrings(observed.phrases, news.phrases)
          ) {
            return observed;
          }
          // PUT replaces the vocabulary: an empty string clears a field the
          // props no longer set.
          const { data } = yield* update({
            TRANSCRIPTION_VOCABULARY_ID: observed.id,
            name: news.name ?? "",
            phrases: news.phrases,
            passthrough: news.passthrough ?? "",
          });
          return toAttrs(data);
        }),
        delete: Effect.fn(function* ({ output }) {
          yield* del({ TRANSCRIPTION_VOCABULARY_ID: output.id }).pipe(
            Effect.catchTag("NotFound", () => Effect.void),
          );
        }),
        read: Effect.fn(function* ({ output }) {
          if (!output?.id) return undefined;
          return yield* observe(output.id);
        }),
      };
    }),
  );
